// ─── GET /openapi.json — anonymous spec endpoint (U6) ───────────────
//
// The route-as-spec migration added `/api/v1/agent/openapi.json` as
// the new authoritative spec source. The endpoint MUST be reachable
// without a bearer token (codegen tools and Swagger UI consume it
// anonymously) and the body MUST be a valid OpenAPI 3.1 document.
// A regression that mounted the spec endpoint after `requireAgentToken`
// would turn it 401 and break every downstream client — this suite is
// the guard.

describe('Agent API: GET /openapi.json (route-as-spec)', () => {
  it('returns 200 without a bearer token (anonymous fetch contract)', async () => {
    const res = await app.request(`${AGENT_BASE}/openapi.json`, { method: 'GET' })
    expect(res.status).toBe(200)
  })

  it('returns a valid OpenAPI 3.1 document with the documented surface paths', async () => {
    const res = await app.request(`${AGENT_BASE}/openapi.json`, { method: 'GET' })
    const doc = (await res.json()) as Record<string, unknown>

    expect(doc['openapi']).toBe('3.1.0')
    expect(doc).toHaveProperty('info')
    expect(doc).toHaveProperty('paths')

    const paths = doc['paths'] as Record<string, unknown>
    // Pin the agent surface's documented endpoints — a path silently
    // disappearing from the spec (e.g., because a future refactor
    // dropped `router.openapi(route, handler)` for `router.post(...)`)
    // would be invisible without this assertion.
    expect(paths).toHaveProperty('/heartbeat')
    expect(paths).toHaveProperty('/tasks/next')
    expect(paths).toHaveProperty('/tasks/{taskId}/report')
    expect(paths).toHaveProperty('/tasks/{taskId}/zaps')
    expect(paths).toHaveProperty('/tasks/{taskId}/resources')
    expect(paths).toHaveProperty('/errors')
    expect(paths).toHaveProperty('/benchmark')
    expect(paths).toHaveProperty('/cracker/check-update')
    expect(paths).toHaveProperty('/resources/{type}/{id}/download-url')
  })

  it('declares the AgentBearer security scheme on the spec', async () => {
    const res = await app.request(`${AGENT_BASE}/openapi.json`, { method: 'GET' })
    const doc = (await res.json()) as Record<string, unknown>
    const components = doc['components'] as Record<string, unknown>
    const securitySchemes = components['securitySchemes'] as Record<string, unknown>
    expect(securitySchemes).toHaveProperty('AgentBearer')
  })

  it('emits oneOf with both updateAvailable arms for the cracker check-update response', async () => {
    // The crackerCheckUpdateResponseSchema is a z.discriminatedUnion
    // on `updateAvailable`. The mountCachedSpec call passes
    // `unionPreferredType: 'oneOf'` so the generated spec must emit
    // `oneOf` (not `anyOf`) for the 200 response. A regression that
    // dropped the generator option, or that collapsed the union to a
    // single arm, would silently break generated agent client codegen.
    // We assert the arm count AND the discriminator literal on each
    // arm so a regression that emits `oneOf` of the wrong shape
    // (single-arm, three-arm, or arms keyed on the wrong field) still
    // fails this test.
    const res = await app.request(`${AGENT_BASE}/openapi.json`, { method: 'GET' })
    const doc = (await res.json()) as Record<string, unknown>
    const paths = doc['paths'] as Record<string, unknown>
    const checkUpdate = paths['/cracker/check-update'] as Record<string, unknown>
    const post = checkUpdate['post'] as Record<string, unknown>
    const responses = post['responses'] as Record<string, unknown>
    const ok = responses['200'] as Record<string, unknown>
    const content = ok['content'] as Record<string, unknown>
    const appJson = content['application/json'] as Record<string, unknown>
    const schemaRoot = appJson['schema'] as Record<string, unknown>
    // The schema may be either an inline `oneOf` block or a `$ref` to
    // a component schema (`CrackerCheckUpdateResponse`) which itself
    // declares `oneOf`. Accept both shapes — the wire contract is
    // satisfied as long as the resolved schema is a `oneOf` with two
    // arms keyed on `updateAvailable`.
    const resolvedSchema: Record<string, unknown> = (() => {
      if ('$ref' in schemaRoot) {
        const refPath = (schemaRoot['$ref'] as string).replace('#/components/schemas/', '')
        const components = doc['components'] as Record<string, unknown>
        const schemas = components['schemas'] as Record<string, unknown>
        return schemas[refPath] as Record<string, unknown>
      }
      return schemaRoot
    })()
    expect(resolvedSchema).toHaveProperty('oneOf')
    const arms = resolvedSchema['oneOf'] as Array<Record<string, unknown>>
    expect(arms).toHaveLength(2)
    // Each arm has `properties.updateAvailable.const` (or `.enum`) that
    // pins true / false. Collect the discriminant values and assert
    // both literals are present, in either order.
    const discriminants = arms.map((arm) => {
      const props = arm['properties'] as Record<string, unknown> | undefined
      const ua = props?.['updateAvailable'] as Record<string, unknown> | undefined
      if (ua && 'const' in ua) return ua['const']
      if (ua && Array.isArray(ua['enum'])) return (ua['enum'] as unknown[])[0]
      return undefined
    })
    // Sort via a stable boolean comparator (Array.prototype.sort needs
    // an explicit compare function for non-string values per the lint
    // rule). Asserting via .toContain on each literal would also work
    // but loses the "both arms present, no extras" intent.
    expect([...discriminants].sort((a, b) => (a === b ? 0 : a ? 1 : -1))).toEqual([false, true])
  })
})

// ─── POST /tasks/:id/report — 200 body shape (post-U6 wire contract) ──
//
// U6 introduced a regression where the non-failure success path
// returned `{ acknowledged: true, retried: false }` instead of the
// pre-U6 bare `{ acknowledged: true }`. The fix preserves the original
// shape on the success path and emits `retried` only on the
// failure-retry branch where it carries useful signal. These tests pin
// both shapes against the wire contract so any future regression
// flipping them would fail loudly.

describe('Agent API: POST /tasks/:id/report — 200 body shape', () => {
  it('returns bare { acknowledged: true } on the success path (no `retried` field)', async () => {
    const token = agentToken(TEST_AGENT_TOKEN)
    const res = await app.request(`${AGENT_BASE}/tasks/42/report`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ status: 'running' }),
    })

    expect(res.status).toBe(200)
    const body = (await res.json()) as Record<string, unknown>
    expect(body['acknowledged']).toBe(true)
    // Pin the omit-on-success behavior — adding `retried: false` to
    // every ack body would silently break any strict
    // (`disallowUnknownFields`) consumer of the agent contract.
    expect(body['retried']).toBeUndefined()
    // No `action` on the ordinary success path (#97 U4).
    expect(body['action']).toBeUndefined()
  })

  it('returns { acknowledged: true, action: "stop" } when the task was preempted (#97 U4)', async () => {
    // Arrange — updateTaskProgress reports the task is paused (preempted),
    // so the progress write was a no-op and the agent must stop.
    updateTaskProgressMock.mockResolvedValueOnce({ stopped: true })

    const token = agentToken(TEST_AGENT_TOKEN)
    const res = await app.request(`${AGENT_BASE}/tasks/42/report`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', authorization: `Bearer ${token}` },
      body: JSON.stringify({ status: 'running' }),
    })

    expect(res.status).toBe(200)
    const body = (await res.json()) as Record<string, unknown>
    expect(body['acknowledged']).toBe(true)
    expect(body['action']).toBe('stop')
  })

  it('returns { acknowledged: true, retried } on the failure-retry branch', async () => {
    // Arrange — force `handleTaskFailure` to report a retry decision.
    const tasksMod = await import('../../src/services/tasks.js')
    ;(
      tasksMod.handleTaskFailure as unknown as {
        mockImplementationOnce: (fn: () => unknown) => void
      }
    ).mockImplementationOnce(() => Promise.resolve({ retried: true }))

    const token = agentToken(TEST_AGENT_TOKEN)
    const res = await app.request(`${AGENT_BASE}/tasks/42/report`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ status: 'failed', errors: ['gpu hung'] }),
    })

    expect(res.status).toBe(200)
    const body = (await res.json()) as Record<string, unknown>
    expect(body['acknowledged']).toBe(true)
    expect(body['retried']).toBe(true)
  })

  it('returns action:stop when a failed report targets a preempted task (#97 U6)', async () => {
    // handleTaskFailure reports the task is paused (preempted) — the failure
    // must not un-pause it via the retry branch; the agent is told to stop.
    const tasksMod = await import('../../src/services/tasks.js')
    ;(
      tasksMod.handleTaskFailure as unknown as {
        mockImplementationOnce: (fn: () => unknown) => void
      }
    ).mockImplementationOnce(() => Promise.resolve({ stopped: true }))

    const token = agentToken(TEST_AGENT_TOKEN)
    const res = await app.request(`${AGENT_BASE}/tasks/42/report`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', authorization: `Bearer ${token}` },
      body: JSON.stringify({ status: 'failed', errors: ['gpu hung'] }),
    })

    expect(res.status).toBe(200)
    const body = (await res.json()) as Record<string, unknown>
    expect(body['acknowledged']).toBe(true)
    expect(body['action']).toBe('stop')
    expect(body['retried']).toBeUndefined()
  })

  it('rejects non-numeric path param with 400 + VALIDATION_ERROR (zod coerce edge case)', async () => {
    // Arrange — the new `z.coerce.number().int().positive()` schema
    // replaces the old hand-rolled `Number.isNaN || taskId <= 0`
    // guard. Pin the equivalence so a future schema relaxation that
    // dropped `.positive()` or `.int()` would fail loudly.
    const token = agentToken(TEST_AGENT_TOKEN)
    const res = await app.request(`${AGENT_BASE}/tasks/abc/report`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ status: 'running' }),
    })

    expect(res.status).toBe(400)
    await expectAgentValidationError(res)
  })

  it('rejects zero path param with 400 + VALIDATION_ERROR (`.positive()` boundary)', async () => {
    const token = agentToken(TEST_AGENT_TOKEN)
    const res = await app.request(`${AGENT_BASE}/tasks/0/report`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ status: 'running' }),
    })

    expect(res.status).toBe(400)
    await expectAgentValidationError(res)
  })

  it('rejects path param above PostgreSQL int4 max with 400 + VALIDATION_ERROR', async () => {
    // 2_147_483_648 is MAX_PG_INT4 + 1. Without an upper bound on
    // taskIdParamSchema, this value would coerce successfully through
    // `.coerce.number().int().positive()` and reach the service layer,
    // where the PostgreSQL `serial` column would throw at the DB
    // boundary — surfacing as an opaque 500. The schema's `.max()`
    // boundary keeps the failure mode at the validator (400) where the
    // agent can see a structured envelope and stop polling that ID.
    const token = agentToken(TEST_AGENT_TOKEN)
    const res = await app.request(`${AGENT_BASE}/tasks/2147483648/report`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ status: 'running' }),
    })

    expect(res.status).toBe(400)
    await expectAgentValidationError(res)
  })

  it('returns 400 TASK_ERROR when the campaign has no hash list (silent data-loss guard)', async () => {
    // Arrange — force `updateTaskProgress` to return the new
    // `{error}` shape that the service now emits when the agent
    // submits cracked results against a campaign with no
    // `hashListId`. Before this guard, the service logged the
    // condition and fell through to a successful response, which
    // silently dropped the cracked hashes on the floor and let the
    // campaign aggregate tick forward on phantom progress. The
    // route's `'error' in result` branch now surfaces this as a
    // 400 + TASK_ERROR so the agent can quarantine the report
    // instead of marking the task done.
    const tasksMod = await import('../../src/services/tasks.js')
    ;(
      tasksMod.updateTaskProgress as unknown as {
        mockImplementationOnce: (fn: () => unknown) => void
      }
    ).mockImplementationOnce(() =>
      Promise.resolve({
        error:
          'Campaign has no associated hash list; cracked results cannot be stored. Check campaign configuration before resubmitting.',
      })
    )

    const token = agentToken(TEST_AGENT_TOKEN)
    const res = await app.request(`${AGENT_BASE}/tasks/42/report`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({
        status: 'completed',
        results: [{ hashValue: 'abc', plaintext: 'def' }],
      }),
    })

    // Assert
    expect(res.status).toBe(400)
    const body = (await res.json()) as { error: Record<string, unknown> }
    expect(body.error.code).toBe('TASK_ERROR')
    // Pin the message verbatim so future service-layer wording
    // changes are caught at the contract layer; agents may surface
    // this string to operators.
    expect(body.error.message).toMatch(/no associated hash list/i)
  })
})

// ─── Errored-agent strict-middleware coverage across work endpoints ──
//
// /heartbeat uses `requireAgentTokenForHeartbeatRecovery` (lenient so
// an errored agent can post a clean heartbeat to recover). Every
// other authenticated route uses the strict `requireAgentToken` which
// rejects agents in `status='error'` with 401 + AUTH_TOKEN_INVALID.
//
// The /tasks/next case is already pinned above; this suite extends
// the same guard across /errors, /benchmark, /resources/*, and
// /cracker/* so a future regression that accidentally swapped the
// middleware on any of them would fail loudly.

/**
 * Assert the documented Agent API auth-invalid envelope
 * (`{error: {code: 'AUTH_TOKEN_INVALID', ...}}` at HTTP 401). A future
 * regression that returned 401 with a different envelope code (e.g.,
 * a new `AUTH_AGENT_ERRORED` discriminator) would land green if we
 * only asserted status code — the envelope code IS the contract for
 * agent client error switching.
 */
async function expectAgentAuthInvalid(res: Response): Promise<void> {
  expect(res.status).toBe(401)
  const body = (await res.json()) as Record<string, unknown>
  expect(body).toHaveProperty('error')
  const err = body['error'] as Record<string, unknown>
  expect(err['code']).toBe('AUTH_TOKEN_INVALID')
  expect(typeof err['message']).toBe('string')
}

describe('Agent API: errored-agent rejection across work endpoints', () => {
  const TEST_AGENT_TOKEN_LOCAL = 'test-agent-preshared-token'
  const errorAgentToken = () => agentToken(TEST_AGENT_TOKEN_LOCAL)

  function withErroredAgent(fn: () => Promise<void>): () => Promise<void> {
    return async () => {
      const priorStatus = mockAgent.status
      mockAgent.status = 'error'
      try {
        await fn()
      } finally {
        mockAgent.status = priorStatus
      }
    }
  }

  it(
    'rejects errored agents on POST /errors',
    withErroredAgent(async () => {
      const res = await app.request(`${AGENT_BASE}/errors`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          authorization: `Bearer ${errorAgentToken()}`,
        },
        body: JSON.stringify({ severity: 'warning', message: 'test' }),
      })
      await expectAgentAuthInvalid(res)
    })
  )

  it(
    'rejects errored agents on POST /benchmark',
    withErroredAgent(async () => {
      const res = await app.request(`${AGENT_BASE}/benchmark`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          authorization: `Bearer ${errorAgentToken()}`,
        },
        body: JSON.stringify({ entries: [] }),
      })
      await expectAgentAuthInvalid(res)
    })
  )

  it(
    'rejects errored agents on GET /resources/:type/:id/download-url',
    withErroredAgent(async () => {
      const res = await app.request(`${AGENT_BASE}/resources/wordlists/1/download-url`, {
        method: 'GET',
        headers: { authorization: `Bearer ${errorAgentToken()}` },
      })
      await expectAgentAuthInvalid(res)
    })
  )

  it(
    'rejects errored agents on POST /cracker/check-update',
    withErroredAgent(async () => {
      const res = await app.request(`${AGENT_BASE}/cracker/check-update`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          authorization: `Bearer ${errorAgentToken()}`,
        },
        body: JSON.stringify({
          engine: 'hashcat',
          platform: 'linux-x64',
          version: '6.2.7',
        }),
      })
      await expectAgentAuthInvalid(res)
    })
  )

  it(
    'STILL ACCEPTS errored agents on POST /heartbeat (recovery middleware)',
    withErroredAgent(async () => {
      // Positive counterpart to the strict-rejection block above:
      // /heartbeat is the one route that uses
      // requireAgentTokenForHeartbeatRecovery (lenient) so an agent
      // forced into status='error' by a prior fatal heartbeat can
      // recover. A regression that swapped this middleware to the
      // strict variant would land green on the four routes above and
      // only surface as a runtime failure when a fielded agent in
      // error state tried to recover. This test guards against that.
      const res = await app.request(`${AGENT_BASE}/heartbeat`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          authorization: `Bearer ${errorAgentToken()}`,
        },
        body: JSON.stringify({ status: 'online' }),
      })
      expect(res.status).toBe(200)
      const body = (await res.json()) as Record<string, unknown>
      expect(body['acknowledged']).toBe(true)
    })
  )
})

// ─── ZapResponse wire shape regression test ─────────────────────────
//
// U6 initially declared ZapResponse as `{ taskId, hashes }` while
// `getZapsForTask` actually returns the zaps envelope. #182 changed
// that envelope from `{ zaps, hasMore }` to `{ zaps, nextCursor }`
// (opaque composite cursor). This test pins the current contract
// against the real service mock so the wire shape and the spec can
// never silently diverge again.

describe('Agent API: POST /tasks/:id/report — wire shape', () => {
  it('returns bare { acknowledged: true } body on the non-failure path', async () => {
    // Arrange — default updateTaskProgress mock already returns the
    // {task} success branch; route is supposed to emit the bare
    // taskReportAckSchema body (no `retried` field).
    const token = agentToken(TEST_AGENT_TOKEN)
    const res = await app.request(`${AGENT_BASE}/tasks/42/report`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ status: 'running' }),
    })

    expect(res.status).toBe(200)
    const body = (await res.json()) as Record<string, unknown>
    expect(body['acknowledged']).toBe(true)
    // Negative-shape assertion: the bug PR #190 originally shipped had
    // `retried: false` on the non-failure path, breaking consumers with
    // `disallowUnknownFields`. The retried key MUST only appear on the
    // failure-retry branch — pin its absence on the bare-success path.
    expect(body['retried']).toBeUndefined()
  })
})

describe('Agent API: GET /tasks/:id/zaps — wire shape', () => {
  it('returns { zaps, nextCursor } body matching getZapsForTask runtime shape', async () => {
    // Arrange — override the default mock with a non-empty payload and a
    // continuation token so the field-shape assertion has real data.
    const tasksMod = await import('../../src/services/tasks.js')
    ;(
      tasksMod.getZapsForTask as unknown as {
        mockImplementationOnce: (fn: () => unknown) => void
      }
    ).mockImplementationOnce(() =>
      Promise.resolve({ zaps: ['hash1', 'hash2'], nextCursor: 'opaque-token' })
    )

    const token = agentToken(TEST_AGENT_TOKEN)
    const res = await app.request(`${AGENT_BASE}/tasks/42/zaps`, {
      method: 'GET',
      headers: { authorization: `Bearer ${token}` },
    })

    expect(res.status).toBe(200)
    const body = (await res.json()) as Record<string, unknown>
    expect(body).toHaveProperty('zaps')
    expect(body).toHaveProperty('nextCursor')
    expect(Array.isArray(body['zaps'])).toBe(true)
    expect(body['nextCursor']).toBe('opaque-token')
    // `hasMore` was removed in #182 — pin its absence so a regression
    // can't re-add the redundant key alongside `nextCursor`.
    expect(body['hasMore']).toBeUndefined()
    // Negative-shape assertions catch a regression that would re-add
    // the wrong keys (`taskId`/`hashes`) and silently break agent
    // codegen consumers parsing this response.
    expect(body['taskId']).toBeUndefined()
    expect(body['hashes']).toBeUndefined()
  })

  it('emits nextCursor: null (explicit key) at exhaustion', async () => {
    const tasksMod = await import('../../src/services/tasks.js')
    ;(
      tasksMod.getZapsForTask as unknown as {
        mockImplementationOnce: (fn: () => unknown) => void
      }
    ).mockImplementationOnce(() => Promise.resolve({ zaps: ['only-hash'], nextCursor: null }))

    const token = agentToken(TEST_AGENT_TOKEN)
    const res = await app.request(`${AGENT_BASE}/tasks/42/zaps`, {
      method: 'GET',
      headers: { authorization: `Bearer ${token}` },
    })

    expect(res.status).toBe(200)
    const body = (await res.json()) as Record<string, unknown>
    // Exhaustion is an explicit null, never an absent key — a client can
    // terminate on `nextCursor === null` without also handling absence.
    expect(body).toHaveProperty('nextCursor')
    expect(body['nextCursor']).toBeNull()
  })
})

// ─── GET /tasks/:id/zaps — malformed cursor is 400, never 500/404 ────
//
// The `cursor` param is agent-controlled input decoded at the query
// boundary (zapQuerySchema). A malformed / out-of-range token must fail
// validation and return the agent VALIDATION_ERROR envelope (400) via
// defaultHook — never a 500 (Invalid Date reaching the DB) and never a
// 404 (the service's not-found path). Validation runs before the handler,
// so the mocked getZapsForTask is never reached on these paths.

function encodeCursorToken(payload: unknown): string {
  return Buffer.from(JSON.stringify(payload), 'utf8').toString('base64url')
}

describe('Agent API: GET /tasks/:id/zaps — malformed cursor', () => {
  const cases: ReadonlyArray<{ name: string; cursor: string }> = [
    { name: 'non-base64url garbage', cursor: '!!!not-a-cursor!!!' },
    {
      name: 'out-of-range id (beyond int4)',
      cursor: encodeCursorToken({ c: 1_752_000_000_000, i: 2_147_483_648 }),
    },
    // The load-bearing case: a structurally valid but out-of-Date-range c
    // would otherwise decode to an Invalid Date, reach Drizzle, and leak a
    // 500. Bounding c at decode keeps it on the 400 path.
    {
      name: 'out-of-range c (beyond JS Date range)',
      cursor: encodeCursorToken({ c: 8_640_000_000_000_001, i: 1 }),
    },
  ]

  for (const { name, cursor } of cases) {
    it(`returns 400 VALIDATION_ERROR for ${name}`, async () => {
      const token = agentToken(TEST_AGENT_TOKEN)
      const res = await app.request(
        `${AGENT_BASE}/tasks/42/zaps?cursor=${encodeURIComponent(cursor)}`,
        { method: 'GET', headers: { authorization: `Bearer ${token}` } }
      )

      expect(res.status).toBe(400)
      const body = (await res.json()) as { error?: { code?: string } }
      expect(body.error?.code).toBe('VALIDATION_ERROR')
    })
  }

  it('accepts a well-formed cursor and reaches the service (200)', async () => {
    // A valid token passes validation and hits the default mock → 200.
    const validCursor = encodeCursorToken({ c: 1_752_000_000_123, i: 7 })
    const token = agentToken(TEST_AGENT_TOKEN)
    const res = await app.request(
      `${AGENT_BASE}/tasks/42/zaps?cursor=${encodeURIComponent(validCursor)}`,
      { method: 'GET', headers: { authorization: `Bearer ${token}` } }
    )

    expect(res.status).toBe(200)
  })

  it('treats an empty cursor (?cursor=) as absent → 200, not 400', async () => {
    // A client serializing a nil/absent token as an empty string must
    // restart the walk from the beginning, not get stuck on a 400.
    const token = agentToken(TEST_AGENT_TOKEN)
    const res = await app.request(`${AGENT_BASE}/tasks/42/zaps?cursor=`, {
      method: 'GET',
      headers: { authorization: `Bearer ${token}` },
    })

    expect(res.status).toBe(200)
  })
})

